from bcc import BPF, BPFProgType
import ctypes as ct
import time
import sys
import os

# BPF program for counting strlen return values
bpf_text_count = """
BPF_HISTOGRAM(ret_hist);

int count_strlen_ret(struct pt_regs *ctx) {
    int ret = PT_REGS_RC(ctx);
    if (ret > 0)
        ret_hist.increment(bpf_log2l(ret));
    return 0;
}
"""

# BPF program for submitting resolver and implementation addresses
bpf_text_addr = """
BPF_PERF_OUTPUT(events);

struct data_t {
    u64 resolver;
    u64 impl;
};

int submit_strlen_addrs(struct pt_regs *ctx) {
    struct data_t data = {};
    data.resolver = (u64)PT_REGS_PARM1(ctx);
    data.impl = (u64)PT_REGS_PARM2(ctx);
    events.perf_submit(ctx, &data, sizeof(data));
    return 0;
}
"""

class AddrData(ct.Structure):
    _fields_ = [
        ("resolver", ct.c_ulonglong),
        ("impl", ct.c_ulonglong),
    ]

def get_strlen_symbol(libc_path):
    from bcc import SymbolCache
    sym_cache = SymbolCache(-1, [libc_path])
    addr = sym_cache.resolve_name(libc_path, "strlen")
    if addr is None:
        raise Exception("Could not find strlen symbol in %s" % libc_path)
    return addr

def set_strlen_addrs(libc_path):
    # Attach a uprobe to strlen to get resolver and impl addresses
    b = BPF(text=bpf_text_addr)
    data = {}

    def callback(cpu, data_ptr, size):
        event = ct.cast(data_ptr, ct.POINTER(AddrData)).contents
        data['resolver'] = event.resolver
        data['impl'] = event.impl

    b["events"].open_perf_buffer(callback)
    b.attach_uprobe(name=libc_path, sym="strlen", fn_name="submit_strlen_addrs")
    # Call strlen to trigger the probe
    import ctypes
    libc = ctypes.CDLL(libc_path)
    libc.strlen(b"test")
    for _ in range(10):
        b.perf_buffer_poll(timeout=100)
        if 'resolver' in data and 'impl' in data:
            break
    b.detach_uprobe(name=libc_path, sym="strlen")
    if 'resolver' not in data or 'impl' not in data:
        raise Exception("Failed to get resolver/impl addresses")
    return data['resolver'], data['impl']

def find_impl_offset(libc_path, resolver_addr, impl_addr):
    return impl_addr - resolver_addr

def main():
    libc_path = BPF.Get_libc_path()
    strlen_addr = get_strlen_symbol(libc_path)
    resolver_addr, impl_addr = set_strlen_addrs(libc_path)
    offset = find_impl_offset(libc_path, resolver_addr, impl_addr)

    # Attach kretprobe to the implementation function
    b = BPF(text=bpf_text_count)
    impl_func_addr = strlen_addr + offset
    b.attach_uprobe(name=libc_path, addr=impl_func_addr, fn_name="count_strlen_ret", pid=-1, retprobe=True)

    print("Tracing strlen return values... Hit Ctrl-C to end.")
    try:
        while True:
            time.sleep(1)
            print("\nHistogram of strlen return values:")
            b["ret_hist"].print_log2_hist("strlen return")
            b["ret_hist"].clear()
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
